public static MyService getInstance() {
    if (instance == null) {
        instance = new MyService();
    }
    return instance;
}

public final class Service {
    private Service() {}
    private static class Holder {
        private static final Service INSTANCE = new Service();
    }
    public static Service getInstance() {
        return Holder.INSTANCE;
    }
}

abstract class DialogCreator {
    public void show() {
        Button ok = createButton();
        ok.paint();
    }
    protected abstract Button createButton();
}

public void notifyAll(String msg) {
    for (Observer observer : observers) {
        observer.update(msg);
    }
}

public interface WidgetFactory {
    Button createButton();
    Checkbox createCheckbox();
}

public class Document implements Cloneable {
    private String content;
    public Document(Document target) {
        if (target != null) this.content = target.content;
    }
    public Document clone() { return new Document(this); }
}

public class CableAdapter implements TypeC {
    private final UsbCable oldCable;
    public CableAdapter(UsbCable old) { this.oldCable = old; }
    public void connect() { oldCable.plugIn(); }
}

public class MilkDecorator implements Coffee {
    private final Coffee coffee;
    public MilkDecorator(Coffee c) { this.coffee = c; }
    public double getCost() { return coffee.getCost() + 0.5; }
}

public class ProxyImage implements Image {
    private RealImage realImage;
    private String filename;
    public void display() {
        if (realImage == null) realImage = new RealImage(filename);
        realImage.display();
    }
}

public class Context {
    private Strategy strategy;
    public void execute() {
        strategy.algorithm();
    }
}

public abstract class Importer {
    public final void importData() {
        read();
        parse();
    }
    protected abstract void read();
    protected abstract void parse();
}
